select location, case when budget >= 4237000 then 'high' when budget >= 1794000 then 'mid' else 'low' end as budget_bucket, case when dept_name in ('Finance', 'Marketing') then 'tier_1' else 'other' end as dept_name_group, max(budget) - min(budget) as budget_range, round((100 * sum(case when dept_name = 'Sales' then 1 else 0 end)) / count(*), 1) as pct_sales from departments group by location, case when budget >= 4237000 then 'high' when budget >= 1794000 then 'mid' else 'low' end, case when dept_name in ('Finance', 'Marketing') then 'tier_1' else 'other' end order by location
